-- Aprenda se Divertindo · 109 · Simulado 4 da Trilha Policial (foco PC-BA)
-- Rode depois do 108-ranking-simulado-amigos.sql. Cole tudo no SQL Editor e clique em Run.
-- Cria e publica o Simulado 4 da trilha Policial: abre no sábado, 14/11/2026, às 0h, e fecha no domingo, 15/11/2026, às 23h59.
-- 100 questões de A a E, estilo AOCP (Investigador PC-BA), com casos práticos, 4 horas de prova (como no edital).
-- Conhecimentos gerais (40): Português 10, Raciocínio Lógico 7, Informática 7, Atualidades 4, Igualdade Racial e de Gênero 4,
--   Medicina Legal 4, Legislação Geral 4. Específicos (60): Penal 10, Processo Penal 9, Legislação Extravagante 9,
--   Contabilidade 8, Constitucional 8, Administrativo 8, Estatística 8.
-- Gabarito equilibrado: 20 questões com cada letra (A a E), sem três letras iguais seguidas.
-- Gabarito comentado liberado na segunda, 16/11, às 0h. Rodar de novo atualiza as questões, desde que ninguém tenha começado.

do $$
declare sid bigint; lista jsonb := $q$[{"materia": "port", "texto_base": "Durante décadas, a cena do crime foi lida sobretudo com os olhos: a posição do corpo, a marca no batente, o copo esquecido sobre a mesa. Hoje, boa parte dos vestígios que interessam à investigação não se vê a olho nu. Está no celular apreendido, na nuvem que guarda fotografias, no registro de uma antena que captou o sinal de um aparelho às três da manhã. A cena do crime, por assim dizer, ganhou uma extensão invisível, e quem não souber percorrê-la corre o risco de chegar tarde à verdade.\n\nEssa mudança, contudo, não torna obsoletas as virtudes clássicas do investigador. Ao contrário: quanto maior o volume de dados, mais necessário se faz o discernimento para separar o relevante do acessório. Um extrato de mensagens não fala por si; precisa ser contextualizado, confrontado com depoimentos e com outros vestígios. Além disso, a prova digital é frágil de um modo particular — pode ser alterada sem deixar marcas aparentes —, razão pela qual sua coleta exige cuidados com a cadeia de custódia que nem sempre são observados. A tecnologia ampliou o alcance da investigação, mas não dispensou o método; apenas o tornou mais exigente.", "enunciado": "De acordo com o texto, a multiplicação dos vestígios digitais", "opcoes": ["tornou o método investigativo mais exigente, sem substituí-lo.", "eliminou a necessidade de examinar a cena física do crime.", "tornou dispensáveis os depoimentos colhidos das testemunhas do fato.", "reduziu a importância do discernimento do investigador.", "garantiu provas imunes a alterações e a fraudes."], "gabarito": 0, "explicacao": "O último período resume a tese: a tecnologia ampliou o alcance da investigação, mas não dispensou o método, apenas o tornou mais exigente. O texto diz o contrário das demais: o discernimento ficou mais necessário, os depoimentos continuam servindo de confronto e a prova digital é frágil."}, {"materia": "port", "texto_base": "Durante décadas, a cena do crime foi lida sobretudo com os olhos: a posição do corpo, a marca no batente, o copo esquecido sobre a mesa. Hoje, boa parte dos vestígios que interessam à investigação não se vê a olho nu. Está no celular apreendido, na nuvem que guarda fotografias, no registro de uma antena que captou o sinal de um aparelho às três da manhã. A cena do crime, por assim dizer, ganhou uma extensão invisível, e quem não souber percorrê-la corre o risco de chegar tarde à verdade.\n\nEssa mudança, contudo, não torna obsoletas as virtudes clássicas do investigador. Ao contrário: quanto maior o volume de dados, mais necessário se faz o discernimento para separar o relevante do acessório. Um extrato de mensagens não fala por si; precisa ser contextualizado, confrontado com depoimentos e com outros vestígios. Além disso, a prova digital é frágil de um modo particular — pode ser alterada sem deixar marcas aparentes —, razão pela qual sua coleta exige cuidados com a cadeia de custódia que nem sempre são observados. A tecnologia ampliou o alcance da investigação, mas não dispensou o método; apenas o tornou mais exigente.", "enunciado": "No trecho “Um extrato de mensagens não fala por si”, o autor emprega", "opcoes": ["ironia, sugerindo exatamente o oposto do que afirma.", "hipérbole, exagerando a quantidade de mensagens do extrato.", "linguagem figurada, atribuindo ao extrato uma ação humana.", "eufemismo, suavizando uma crítica ao trabalho policial.", "linguagem técnica, própria dos laudos de perícia digital."], "gabarito": 2, "explicacao": "Falar é ação humana atribuída a um objeto (o extrato): trata-se de personificação (prosopopeia), uma figura de linguagem. O autor quer dizer que os dados precisam ser interpretados e contextualizados."}, {"materia": "port", "texto_base": "Durante décadas, a cena do crime foi lida sobretudo com os olhos: a posição do corpo, a marca no batente, o copo esquecido sobre a mesa. Hoje, boa parte dos vestígios que interessam à investigação não se vê a olho nu. Está no celular apreendido, na nuvem que guarda fotografias, no registro de uma antena que captou o sinal de um aparelho às três da manhã. A cena do crime, por assim dizer, ganhou uma extensão invisível, e quem não souber percorrê-la corre o risco de chegar tarde à verdade.\n\nEssa mudança, contudo, não torna obsoletas as virtudes clássicas do investigador. Ao contrário: quanto maior o volume de dados, mais necessário se faz o discernimento para separar o relevante do acessório. Um extrato de mensagens não fala por si; precisa ser contextualizado, confrontado com depoimentos e com outros vestígios. Além disso, a prova digital é frágil de um modo particular — pode ser alterada sem deixar marcas aparentes —, razão pela qual sua coleta exige cuidados com a cadeia de custódia que nem sempre são observados. A tecnologia ampliou o alcance da investigação, mas não dispensou o método; apenas o tornou mais exigente.", "enunciado": "A expressão “Ao contrário”, no início do segundo parágrafo, introduz uma ideia que", "opcoes": ["nega que as virtudes clássicas tenham se tornado obsoletas.", "confirma que a tecnologia substituiu o método tradicional.", "exemplifica os cuidados exigidos pela cadeia de custódia.", "contradiz a afirmação de que os vestígios digitais são invisíveis.", "conclui o raciocínio sobre a fragilidade da prova digital."], "gabarito": 0, "explicacao": "Logo antes, o autor afirma que a mudança não torna obsoletas as virtudes clássicas. “Ao contrário” reforça essa negação: com mais dados, o discernimento fica ainda mais necessário."}, {"materia": "port", "texto_base": "Durante décadas, a cena do crime foi lida sobretudo com os olhos: a posição do corpo, a marca no batente, o copo esquecido sobre a mesa. Hoje, boa parte dos vestígios que interessam à investigação não se vê a olho nu. Está no celular apreendido, na nuvem que guarda fotografias, no registro de uma antena que captou o sinal de um aparelho às três da manhã. A cena do crime, por assim dizer, ganhou uma extensão invisível, e quem não souber percorrê-la corre o risco de chegar tarde à verdade.\n\nEssa mudança, contudo, não torna obsoletas as virtudes clássicas do investigador. Ao contrário: quanto maior o volume de dados, mais necessário se faz o discernimento para separar o relevante do acessório. Um extrato de mensagens não fala por si; precisa ser contextualizado, confrontado com depoimentos e com outros vestígios. Além disso, a prova digital é frágil de um modo particular — pode ser alterada sem deixar marcas aparentes —, razão pela qual sua coleta exige cuidados com a cadeia de custódia que nem sempre são observados. A tecnologia ampliou o alcance da investigação, mas não dispensou o método; apenas o tornou mais exigente.", "enunciado": "O trecho entre travessões “— pode ser alterada sem deixar marcas aparentes —” tem a função de", "opcoes": ["explicar em que consiste a fragilidade particular da prova digital.", "fazer uma ressalva que contradiz a ideia exposta imediatamente antes dele.", "concluir que são necessárias novas leis sobre o tema.", "enumerar os vestígios encontrados no local do crime.", "reproduzir a fala de um perito citado pelo autor do texto."], "gabarito": 0, "explicacao": "Os travessões isolam um trecho explicativo: dizem de que “modo particular” a prova digital é frágil. Não há ressalva, citação, enumeração nem conclusão."}, {"materia": "port", "texto_base": "Durante décadas, a cena do crime foi lida sobretudo com os olhos: a posição do corpo, a marca no batente, o copo esquecido sobre a mesa. Hoje, boa parte dos vestígios que interessam à investigação não se vê a olho nu. Está no celular apreendido, na nuvem que guarda fotografias, no registro de uma antena que captou o sinal de um aparelho às três da manhã. A cena do crime, por assim dizer, ganhou uma extensão invisível, e quem não souber percorrê-la corre o risco de chegar tarde à verdade.\n\nEssa mudança, contudo, não torna obsoletas as virtudes clássicas do investigador. Ao contrário: quanto maior o volume de dados, mais necessário se faz o discernimento para separar o relevante do acessório. Um extrato de mensagens não fala por si; precisa ser contextualizado, confrontado com depoimentos e com outros vestígios. Além disso, a prova digital é frágil de um modo particular — pode ser alterada sem deixar marcas aparentes —, razão pela qual sua coleta exige cuidados com a cadeia de custódia que nem sempre são observados. A tecnologia ampliou o alcance da investigação, mas não dispensou o método; apenas o tornou mais exigente.", "enunciado": "Em “razão pela qual sua coleta exige cuidados”, o pronome “sua” retoma", "opcoes": ["a cena do crime.", "a investigação.", "a prova digital.", "a tecnologia.", "a cadeia de custódia."], "gabarito": 2, "explicacao": "Quem é coletada com cuidado é a prova digital, mencionada imediatamente antes: “a prova digital é frágil [...], razão pela qual sua coleta exige cuidados”."}, {"materia": "port", "texto_base": "", "enunciado": "Assinale a alternativa em que o acento indicativo de crase está empregado corretamente.", "opcoes": ["A equipe chegou à pé ao local indicado na denúncia.", "O laudo foi entregue à uma servidora do cartório.", "O suspeito ficou frente à frente com a vítima na delegacia.", "O delegado referiu-se à testemunha que chegou atrasada.", "O investigador começou à analisar o celular apreendido."], "gabarito": 3, "explicacao": "“Referir-se a” + “a testemunha” = “à testemunha”. Não há crase antes de verbo (começou a analisar), antes de palavra masculina (a pé), antes de artigo indefinido (a uma) nem entre palavras repetidas (frente a frente)."}, {"materia": "port", "texto_base": "", "enunciado": "Assinale a frase correta quanto à concordância verbal, segundo a norma-padrão.", "opcoes": ["Fazem três meses que o inquérito está parado.", "Faz dois anos que a investigação foi arquivada.", "Haviam muitas provas contra o suspeito.", "Devem haver outras testemunhas do crime.", "Existe, nos autos, vários depoimentos contraditórios."], "gabarito": 1, "explicacao": "“Fazer” indicando tempo é impessoal e fica no singular (faz dois anos). “Haver” no sentido de existir também é impessoal: havia provas, deve haver testemunhas. Já “existir” é pessoal e concorda: existem vários depoimentos."}, {"materia": "port", "texto_base": "", "enunciado": "Quanto à regência verbal, está de acordo com a norma-padrão:", "opcoes": ["O agente obedeceu o comando dado pelo seu superior.", "A equipe chegou no local do crime por volta das 22h.", "O investigador assistiu ao vídeo das câmeras de segurança.", "O escrivão esqueceu do horário marcado para a audiência.", "O delegado preferiu mais ouvir a vítima do que o suspeito."], "gabarito": 2, "explicacao": "“Assistir” no sentido de ver exige a preposição “a”: assistiu ao vídeo. O correto nos demais é: preferiu ouvir a vítima ao suspeito (sem “mais” e “do que”), chegou ao local, esqueceu o horário ou esqueceu-se do horário e obedeceu ao comando."}, {"materia": "port", "texto_base": "", "enunciado": "Assinale a alternativa correta quanto à colocação pronominal.", "opcoes": ["Ninguém viu-o sair do prédio naquela noite.", "Me disseram que o suspeito fugiu pelos fundos.", "O delegado tinha informado-me sobre a operação.", "Quando encontraram-no, o suspeito estava ferido.", "Não se sabe ainda quem efetuou os disparos."], "gabarito": 4, "explicacao": "A palavra negativa “não” atrai o pronome (próclise). Não se inicia frase com pronome oblíquo átono (Disseram-me). Não há ênclise a particípio (tinha-me informado), e conjunção subordinativa e pronome indefinido atraem o pronome (quando o encontraram, ninguém o viu)."}, {"materia": "port", "texto_base": "", "enunciado": "Assinale a alternativa corretamente pontuada.", "opcoes": ["O delegado determinou, a oitiva imediata das testemunhas.", "A vítima, procurou a delegacia na manhã seguinte ao fato.", "Na manhã seguinte a vítima procurou, a delegacia do bairro.", "Os peritos que chegaram cedo, isolaram a área do crime.", "Os peritos, que chegaram cedo, isolaram a área do crime."], "gabarito": 4, "explicacao": "Entre vírgulas está uma oração adjetiva explicativa, o que é correto. Nas demais, a vírgula separa indevidamente o sujeito do verbo ou o verbo do seu complemento."}, {"materia": "rl", "texto_base": "", "enunciado": "A negação da proposição “Todo investigador é atento” é:", "opcoes": ["Nenhum investigador é atento.", "Todo investigador não é atento.", "Algum investigador é atento.", "Algum investigador não é atento.", "Nenhum ser atento é investigador."], "gabarito": 3, "explicacao": "Para negar “todo A é B”, basta um caso contrário: “algum A não é B”. “Nenhum investigador é atento” é a contrária, não a negação."}, {"materia": "rl", "texto_base": "", "enunciado": "Uma proposição logicamente equivalente a “Se o suspeito fugiu, então ele é culpado” é:", "opcoes": ["Se o suspeito não é culpado, então ele não fugiu.", "Se o suspeito não fugiu, então ele não é culpado.", "Se o suspeito é culpado, então ele fugiu.", "O suspeito fugiu ou não é culpado.", "O suspeito fugiu e não é culpado."], "gabarito": 0, "explicacao": "A contrapositiva (se não q, então não p) é equivalente à condicional. Outra equivalente seria “o suspeito não fugiu ou é culpado”. “Fugiu e não é culpado” é a negação da condicional."}, {"materia": "rl", "texto_base": "", "enunciado": "A negação de “Ana é perita e Bruno é escrivão” é:", "opcoes": ["Ana não é perita e Bruno não é escrivão.", "Ana não é perita e Bruno é escrivão.", "Ana não é perita ou Bruno não é escrivão.", "Ana é perita ou Bruno é escrivão, mas não ambos.", "Se Ana é perita, então Bruno é escrivão."], "gabarito": 2, "explicacao": "Pela lei de De Morgan, a negação de “p e q” é “não p ou não q”: troca-se o “e” pelo “ou” e negam-se as duas partes."}, {"materia": "rl", "texto_base": "", "enunciado": "Uma delegacia tem 7 investigadores disponíveis e precisa formar uma equipe de 3 para uma operação, sem distinção de funções. O número de equipes diferentes possíveis é", "opcoes": ["42.", "70.", "210.", "21.", "35."], "gabarito": 4, "explicacao": "A ordem não importa, então é combinação: C(7,3) = 7·6·5 / 3·2·1 = 210/6 = 35. O 210 seria o arranjo, em que a ordem importa."}, {"materia": "rl", "texto_base": "", "enunciado": "Entre 10 suspeitos, 4 têm antecedentes criminais. Sorteando-se 2 deles ao acaso, sem reposição, a probabilidade de que ambos tenham antecedentes é", "opcoes": ["2/9.", "1/15.", "4/25.", "2/15.", "1/5."], "gabarito": 3, "explicacao": "Primeiro sorteio: 4/10. Segundo, sem reposição: 3/9. Probabilidade = 4/10 · 3/9 = 12/90 = 2/15. O 4/25 seria o resultado com reposição."}, {"materia": "rl", "texto_base": "", "enunciado": "Na sequência 2, 6, 12, 20, 30, ..., o próximo termo é", "opcoes": ["42.", "36.", "40.", "38.", "44."], "gabarito": 0, "explicacao": "As diferenças entre os termos crescem de 2 em 2: +4, +6, +8, +10. A próxima é +12, então 30 + 12 = 42. Outra forma de ver: n·(n+1), e 6·7 = 42."}, {"materia": "rl", "texto_base": "", "enunciado": "Um entre três investigadores, A, B e C, escreveu um relatório anônimo. A diz: “Fui eu”. B diz: “Não fui eu”. C diz: “Foi A”. Sabendo que apenas um deles diz a verdade, quem escreveu o relatório foi", "opcoes": ["impossível determinar com esses dados.", "C.", "A.", "B.", "A ou B, indistintamente."], "gabarito": 1, "explicacao": "Se fosse A, as três falas seriam verdadeiras. Se fosse B, todas seriam falsas. Se foi C, só B diz a verdade (“não fui eu”), o que cumpre a condição. Logo, foi C."}, {"materia": "inf", "texto_base": "", "enunciado": "Um servidor recebe e-mail com o logotipo do seu banco pedindo que clique em um link e confirme a senha para evitar o bloqueio da conta. O link leva a uma página falsa. Essa técnica é chamada de", "opcoes": ["keylogger.", "phishing.", "spyware.", "worm.", "ransomware."], "gabarito": 1, "explicacao": "Phishing é a fraude que imita uma instituição confiável para enganar a vítima e obter dados como senhas. Ransomware sequestra arquivos, worm se propaga sozinho pela rede, spyware espiona e keylogger registra o que é digitado."}, {"materia": "inf", "texto_base": "", "enunciado": "Os computadores de um cartório amanhecem com todos os arquivos criptografados e uma mensagem exigindo pagamento em criptomoeda para liberá-los. Trata-se de ataque de", "opcoes": ["ransomware.", "cavalo de troia sem carga maliciosa.", "phishing.", "adware.", "rootkit."], "gabarito": 0, "explicacao": "Ransomware é o malware que torna os dados inacessíveis, em geral por criptografia, e exige resgate. O que previne o prejuízo é ter backup atualizado e guardado fora da rede."}, {"materia": "inf", "texto_base": "", "enunciado": "No Microsoft Excel, as células B2, B3 e B4 contêm 4, 6 e 8, e a célula B5 está vazia. A fórmula =MÉDIA(B2:B5) retorna", "opcoes": ["8.", "o erro #DIV/0!.", "6.", "4,5.", "18."], "gabarito": 2, "explicacao": "A função MÉDIA ignora células vazias: (4 + 6 + 8) / 3 = 6. O resultado 4,5 só sairia se a célula vazia contasse como zero."}, {"materia": "inf", "texto_base": "", "enunciado": "No Windows 10 e 11, o atalho de teclado que abre diretamente o Gerenciador de Tarefas é", "opcoes": ["Alt + F4.", "Ctrl + Shift + Esc.", "Ctrl + Alt + Del.", "Windows + E.", "Windows + D."], "gabarito": 1, "explicacao": "Ctrl + Shift + Esc abre o Gerenciador de Tarefas direto. Ctrl + Alt + Del abre uma tela de opções, Windows + E abre o Explorador de Arquivos, Alt + F4 fecha a janela e Windows + D mostra a área de trabalho."}, {"materia": "inf", "texto_base": "", "enunciado": "O tipo de backup que copia os arquivos alterados desde o último backup completo, acumulando as alterações a cada execução, é o backup", "opcoes": ["espelhado.", "completo.", "diferencial.", "incremental.", "normal."], "gabarito": 2, "explicacao": "O diferencial sempre copia o que mudou desde o último completo, por isso vai crescendo. O incremental copia só o que mudou desde o último backup de qualquer tipo."}, {"materia": "inf", "texto_base": "", "enunciado": "Sobre a navegação anônima (privativa) dos navegadores, é correto afirmar que ela", "opcoes": ["apaga automaticamente os arquivos baixados ao fechar a janela.", "criptografa todos os dados que o usuário envia pela internet.", "torna o endereço IP do usuário invisível para todos os sites que ele visita.", "impede a instalação de programas maliciosos no computador.", "não guarda histórico local, mas provedor e sites ainda registram o acesso."], "gabarito": 4, "explicacao": "A janela anônima só deixa de guardar histórico, cookies e dados de formulário no próprio computador. O provedor, a rede e os sites continuam vendo o acesso, e os downloads permanecem salvos."}, {"materia": "inf", "texto_base": "", "enunciado": "Ao acessar um portal, o usuário percebe que o endereço começa com “https” e exibe um cadeado. Isso indica que", "opcoes": ["o servidor que hospeda o site está localizado no Brasil.", "a comunicação entre o navegador e o site é criptografada.", "o site pertence obrigatoriamente a um órgão do governo.", "a página foi verificada e aprovada pelo antivírus do computador.", "o site está protegido contra qualquer tipo de golpe ou fraude."], "gabarito": 1, "explicacao": "O HTTPS usa criptografia (TLS) para proteger os dados trocados entre navegador e servidor. Ele não garante que o site seja honesto: páginas de phishing também podem ter cadeado."}, {"materia": "Atualidades", "texto_base": "", "enunciado": "A Copa do Mundo de futebol masculino de 2026, a primeira disputada por 48 seleções, teve como países-sede", "opcoes": ["Estados Unidos, Canadá e México.", "México, Colômbia e Estados Unidos.", "Estados Unidos, México e Costa Rica.", "Canadá, México e Brasil.", "Estados Unidos e Canadá, apenas."], "gabarito": 0, "explicacao": "A Copa de 2026 foi dividida entre Estados Unidos, Canadá e México, e foi a primeira com 48 seleções e três países-sede."}, {"materia": "Atualidades", "texto_base": "", "enunciado": "Sancionada em janeiro de 2025, a Lei 15.100 tratou", "opcoes": ["da restrição ao uso de celulares por estudantes nas escolas de educação básica.", "da obrigatoriedade de câmeras corporais para todos os policiais.", "da regulamentação geral do uso de inteligência artificial no Brasil.", "da criação do ensino médio em tempo integral obrigatório.", "da proibição de redes sociais para menores de 16 anos em todo o território nacional."], "gabarito": 0, "explicacao": "A Lei 15.100/2025 restringe o uso de celulares e aparelhos eletrônicos portáteis pelos alunos nas escolas de educação básica, inclusive no recreio. Há exceções para fins pedagógicos, acessibilidade e saúde."}, {"materia": "Atualidades", "texto_base": "", "enunciado": "Os Jogos Olímpicos de Inverno de 2026 foram realizados na Itália, com sede compartilhada pelas cidades de", "opcoes": ["Veneza e Bolonha.", "Roma e Turim.", "Milão e Cortina d’Ampezzo.", "Turim e Florença.", "Nápoles e Milão."], "gabarito": 2, "explicacao": "Os Jogos de Inverno de fevereiro de 2026 tiveram Milão e Cortina d’Ampezzo como sedes (Milano Cortina 2026)."}, {"materia": "Atualidades", "texto_base": "", "enunciado": "Nas eleições gerais de outubro de 2026, além do presidente da República, os eleitores escolheram", "opcoes": ["governadores e vereadores, apenas.", "governadores, senadores, deputados federais e deputados estaduais.", "governadores, prefeitos, senadores, deputados federais e deputados estaduais.", "senadores e deputados federais, apenas.", "prefeitos, vereadores e deputados estaduais."], "gabarito": 1, "explicacao": "As eleições gerais escolhem presidente, governadores, senadores, deputados federais e estaduais (ou distritais). Prefeitos e vereadores são eleitos nas eleições municipais, dois anos depois."}, {"materia": "igual", "texto_base": "", "enunciado": "Para os efeitos do Estatuto da Igualdade Racial (Lei 12.288/2010), considera-se população negra", "opcoes": ["as pessoas com ascendência africana comprovada por documento oficial.", "as pessoas que se autodeclaram pretas e pardas, conforme o quesito cor ou raça do IBGE.", "as pessoas assim classificadas por comissão de heteroidentificação criada pelo Poder Público.", "os descendentes de quilombolas reconhecidos pela Fundação Palmares.", "apenas as pessoas que se autodeclaram pretas, excluídas as pardas."], "gabarito": 1, "explicacao": "O art. 1º, parágrafo único, IV, do Estatuto define população negra como o conjunto de pessoas que se autodeclaram pretas e pardas, conforme o quesito cor ou raça usado pelo IBGE."}, {"materia": "igual", "texto_base": "", "enunciado": "Uma mulher relata ao delegado que o companheiro a humilha, controla seus passos e a afasta de amigos e parentes, o que lhe causa dano emocional. Desde a Lei 14.188/2021, essa conduta", "opcoes": ["configura exclusivamente o crime de constrangimento ilegal.", "é apenas ilícito civil, sem tipificação penal própria.", "só é crime se houver lesão física comprovada por laudo.", "configura injúria, crime contra a honra que se processa por ação penal privada.", "configura o crime de violência psicológica contra a mulher (art. 147-B do CP)."], "gabarito": 4, "explicacao": "A Lei 14.188/2021 criou o art. 147-B do CP: causar dano emocional à mulher por meio de ameaça, humilhação, manipulação, isolamento, controle ou outro meio. Também instituiu o programa Sinal Vermelho."}, {"materia": "igual", "texto_base": "", "enunciado": "Uma mulher pede medida protetiva contra o ex-marido, mas ainda não registrou boletim de ocorrência e não há inquérito instaurado. Pela Lei Maria da Penha, após a Lei 14.550/2023, a medida protetiva", "opcoes": ["exige prévio registro de boletim de ocorrência pela vítima.", "só pode ser concedida depois de instaurado o inquérito policial sobre os fatos narrados.", "só vale se a ação penal for ajuizada em até 30 dias.", "depende da tipificação penal da conduta do agressor.", "pode ser concedida, pois independe de boletim de ocorrência, inquérito ou processo."], "gabarito": 4, "explicacao": "A Lei 14.550/2023 deixou expresso que as medidas protetivas independem da tipificação penal da violência, do ajuizamento de ação, da existência de inquérito ou do registro de boletim de ocorrência."}, {"materia": "igual", "texto_base": "", "enunciado": "Após a Lei 14.994/2024, conhecida como Pacote Antifeminicídio, o feminicídio passou a ser", "opcoes": ["crime autônomo, com pena de reclusão de 12 a 30 anos.", "contravenção penal agravada pela condição de mulher.", "qualificadora do homicídio, com pena de 12 a 30 anos.", "crime autônomo, com pena de reclusão de 20 a 40 anos.", "causa de aumento do homicídio simples, de um terço até a metade."], "gabarito": 3, "explicacao": "A Lei 14.994/2024 tirou o feminicídio do rol de qualificadoras do homicídio e o transformou em crime autônomo (art. 121-A do CP), com pena de 20 a 40 anos de reclusão."}, {"materia": "ml", "texto_base": "", "enunciado": "No exame de uma vítima de asfixia, o perito encontra no pescoço equimoses arredondadas e escoriações em forma de meia-lua, sem qualquer sulco. Esses achados indicam", "opcoes": ["sufocação direta.", "esganadura.", "afogamento.", "estrangulamento por laço.", "enforcamento."], "gabarito": 1, "explicacao": "Na esganadura, a constrição do pescoço é feita com as mãos e deixa equimoses digitais e estigmas ungueais (marcas de unha em meia-lua). Enforcamento e estrangulamento deixam sulco."}, {"materia": "ml", "texto_base": "", "enunciado": "A mancha verde abdominal, primeiro sinal da fase cromática da putrefação, costuma surgir", "opcoes": ["na fossa ilíaca esquerda, por volta de 72 horas após a morte.", "na fossa ilíaca direita, entre 18 e 24 horas após a morte.", "nos membros inferiores, entre 6 e 8 horas após a morte.", "na face, logo na primeira hora após a morte.", "na região do tórax, entre 2 e 4 horas após a morte."], "gabarito": 1, "explicacao": "A mancha verde aparece em geral na fossa ilíaca direita, onde o ceco fica mais perto da parede abdominal, por volta de 18 a 24 horas após a morte."}, {"materia": "ml", "texto_base": "", "enunciado": "Após uma briga, a vítima ficou 40 dias sem poder trabalhar por causa das lesões, mas se recuperou totalmente, sem sequelas. A lesão corporal é classificada como", "opcoes": ["leve, porque não restou sequela permanente.", "leve, pois a incapacidade não passou de 60 dias.", "grave, por perigo de vida, que se presume nesse caso.", "grave, pela incapacidade para as ocupações habituais por mais de 30 dias.", "gravíssima, por ter resultado em incapacidade permanente para o trabalho habitual."], "gabarito": 3, "explicacao": "O art. 129, § 1º, I, do CP qualifica como grave a lesão que resulta em incapacidade para as ocupações habituais por mais de 30 dias. Incapacidade permanente para o trabalho é gravíssima."}, {"materia": "ml", "texto_base": "", "enunciado": "Uma vítima foi atingida por golpe de faca de ponta e gume, que deixou ferimento mais profundo do que largo. O instrumento e a ferida classificam-se, respectivamente, como", "opcoes": ["cortocontundente e cortocontusa.", "perfurocortante e perfuroincisa.", "perfurocontundente e perfurocontusa.", "perfurante e punctória.", "cortante e incisa."], "gabarito": 1, "explicacao": "A faca com ponta e gume age perfurando e cortando: é perfurocortante e produz ferida perfuroincisa. Projétil de arma de fogo é perfurocontundente, e o machado é cortocontundente."}, {"materia": "Legislação Geral", "texto_base": "", "enunciado": "Pela Lei de Acesso à Informação (Lei 12.527/2011), não sendo possível conceder o acesso imediato à informação pedida, o órgão deve responder em prazo", "opcoes": ["de até 15 dias úteis, prorrogável uma vez por igual período.", "não superior a 20 dias, prorrogável por mais 10, com justificativa expressa.", "de até 5 dias, sob pena de responsabilidade do agente.", "não superior a 10 dias, prorrogável por mais 10, sem necessidade de justificativa.", "de até 30 dias, improrrogável."], "gabarito": 1, "explicacao": "O art. 11, §§ 1º e 2º, da LAI fixa prazo não superior a 20 dias, prorrogável por mais 10, mediante justificativa expressa comunicada ao requerente."}, {"materia": "Legislação Geral", "texto_base": "", "enunciado": "Pela Lei 12.527/2011, uma informação classificada no grau secreto fica com acesso restrito pelo prazo máximo de", "opcoes": ["15 anos.", "5 anos.", "25 anos.", "50 anos.", "10 anos."], "gabarito": 0, "explicacao": "O art. 24 da LAI fixa os prazos máximos: ultrassecreta, 25 anos; secreta, 15 anos; reservada, 5 anos."}, {"materia": "Legislação Geral", "texto_base": "", "enunciado": "Entre as alternativas abaixo, NÃO é modalidade de licitação prevista na Lei 14.133/2021:", "opcoes": ["diálogo competitivo.", "pregão.", "concorrência.", "leilão.", "tomada de preços."], "gabarito": 4, "explicacao": "O art. 28 da Lei 14.133/2021 prevê pregão, concorrência, concurso, leilão e diálogo competitivo. Tomada de preços e convite, da antiga Lei 8.666/1993, foram extintos."}, {"materia": "Legislação Geral", "texto_base": "", "enunciado": "Por descuido, sem intenção, um servidor deixa de conferir uma nota fiscal e a Administração paga valor acima do devido. Pela Lei de Improbidade, após a Lei 14.230/2021, essa conduta", "opcoes": ["configura improbidade culposa que causa prejuízo ao erário.", "configura enriquecimento ilícito presumido do servidor.", "não configura improbidade, pois a lei passou a exigir conduta dolosa.", "configura improbidade por violação de princípios, punida só com multa.", "configura improbidade, desde que o prejuízo supere 10 salários mínimos."], "gabarito": 2, "explicacao": "Depois da Lei 14.230/2021, só há ato de improbidade com dolo, inclusive no dano ao erário: a modalidade culposa foi extinta. O servidor ainda pode responder disciplinar e civilmente pelo prejuízo."}, {"materia": "pen", "texto_base": "", "enunciado": "Joel furtou o celular de uma colega de trabalho. Arrependido, devolveu o aparelho intacto, por vontade própria, antes do oferecimento da denúncia. Nessa situação, Joel", "opcoes": ["terá a punibilidade extinta, pela reparação integral do dano.", "responderá apenas por tentativa de furto, em razão da desistência voluntária.", "não responderá por crime, pelo arrependimento eficaz.", "terá a pena reduzida de um a dois terços, pelo arrependimento posterior.", "terá direito ao perdão judicial, por ser réu primário."], "gabarito": 3, "explicacao": "No crime sem violência ou grave ameaça, reparado o dano ou restituída a coisa por ato voluntário até o recebimento da denúncia, a pena é reduzida de 1/3 a 2/3 (art. 16 do CP). O furto já estava consumado, por isso não é arrependimento eficaz."}, {"materia": "pen", "texto_base": "", "enunciado": "Com intenção de matar, Rui dispara contra Léo e o atinge na perna. Tendo munição e podendo continuar atirando, Rui desiste por vontade própria e vai embora. Léo sobrevive. Rui responderá por", "opcoes": ["lesão corporal, pela desistência voluntária.", "tentativa de homicídio, pois a execução já havia começado.", "tentativa de homicídio com redução da pena pelo arrependimento posterior.", "homicídio consumado, pois o dolo era de matar.", "nenhum crime, pois desistiu antes do resultado."], "gabarito": 0, "explicacao": "Na desistência voluntária (art. 15 do CP), o agente que, podendo prosseguir, interrompe a execução por vontade própria responde só pelos atos já praticados, no caso a lesão corporal."}, {"materia": "pen", "texto_base": "", "enunciado": "Réu primário, Vando furtou de um supermercado mercadorias de pequeno valor. Pelo art. 155, § 2º, do Código Penal, o juiz", "opcoes": ["deve absolver o réu, pela insignificância presumida em lei.", "só pode conceder perdão judicial se o objeto for restituído.", "deve aplicar a pena em dobro, por se tratar de furto praticado em estabelecimento comercial.", "deve converter o furto em contravenção penal de menor potencial ofensivo.", "pode substituir a reclusão por detenção, reduzir a pena de 1/3 a 2/3 ou aplicar só multa."], "gabarito": 4, "explicacao": "É o furto privilegiado: criminoso primário e coisa de pequeno valor. O juiz pode trocar reclusão por detenção, diminuir a pena de um a dois terços ou aplicar somente multa. Não se confunde com o princípio da insignificância, construção da jurisprudência."}, {"materia": "pen", "texto_base": "", "enunciado": "Bruno subtrai a carteira de um passageiro no ônibus. Ao ser perseguido pela vítima logo depois, desfere-lhe um soco para garantir a posse do objeto e consegue fugir. Bruno cometeu", "opcoes": ["roubo próprio.", "furto qualificado pela destreza.", "furto seguido de lesão corporal leve.", "extorsão.", "roubo impróprio."], "gabarito": 4, "explicacao": "Se a violência ou a grave ameaça vem logo depois da subtração, para assegurar a posse da coisa ou a impunidade, há roubo impróprio (art. 157, § 1º, do CP). No roubo próprio, a violência é usada para subtrair."}, {"materia": "pen", "texto_base": "", "enunciado": "Criminosos rendem um motorista e o mantêm no carro por duas horas, obrigando-o a sacar dinheiro em caixas eletrônicos com o próprio cartão e senha. Essa conduta, conhecida como “sequestro relâmpago”, configura", "opcoes": ["roubo simples, pois houve subtração de dinheiro.", "extorsão com restrição da liberdade da vítima (art. 158, § 3º, do CP).", "furto mediante fraude, pelo uso do cartão e da senha bancária pertencentes à vítima.", "sequestro e cárcere privado, apenas.", "extorsão mediante sequestro (art. 159 do CP)."], "gabarito": 1, "explicacao": "Quando a extorsão é cometida mediante restrição da liberdade da vítima, condição necessária para obter a vantagem, aplica-se o art. 158, § 3º, do CP. Na extorsão mediante sequestro, a vítima é privada da liberdade e o resgate é condição para soltá-la."}, {"materia": "pen", "texto_base": "", "enunciado": "Um homem engana uma senhora de 75 anos e obtém dela uma transferência bancária. Quanto à ação penal no crime de estelionato, nesse caso ela é", "opcoes": ["pública condicionada à representação da vítima.", "pública incondicionada, porque a vítima tem mais de 70 anos.", "privada subsidiária da pública, em qualquer caso.", "privada, mediante queixa-crime da vítima.", "pública condicionada à requisição do Ministro da Justiça, em qualquer caso."], "gabarito": 1, "explicacao": "Desde o Pacote Anticrime, o estelionato depende de representação, salvo se a vítima for a Administração, criança ou adolescente, pessoa com deficiência mental ou maior de 70 anos ou incapaz (art. 171, § 5º, do CP)."}, {"materia": "pen", "texto_base": "", "enunciado": "Por descuido, um servidor deixa aberto o cofre da repartição, de onde um terceiro subtrai dinheiro público. O servidor repara integralmente o dano antes da sentença irrecorrível. Nesse caso,", "opcoes": ["o servidor responde por prevaricação.", "o servidor responde por peculato doloso, com a pena reduzida pela metade.", "extingue-se a punibilidade do servidor pelo peculato culposo.", "a pena do servidor é reduzida de metade.", "a reparação não produz efeito penal, apenas civil."], "gabarito": 2, "explicacao": "No peculato culposo (art. 312, § 2º), a reparação do dano antes da sentença irrecorrível extingue a punibilidade. Se for feita depois, reduz a pena imposta pela metade (§ 3º)."}, {"materia": "pen", "texto_base": "", "enunciado": "Um investigador deixa de cumprir uma diligência determinada no inquérito porque o investigado é seu amigo de infância e ele quer poupá-lo. O investigador cometeu", "opcoes": ["advocacia administrativa.", "concussão.", "condescendência criminosa.", "prevaricação.", "corrupção passiva."], "gabarito": 3, "explicacao": "Retardar ou deixar de praticar ato de ofício para satisfazer interesse ou sentimento pessoal é prevaricação (art. 319 do CP). Não houve vantagem pedida ou recebida, o que afasta corrupção e concussão."}, {"materia": "pen", "texto_base": "", "enunciado": "Ofendido durante uma discussão num bar, Davi vai para casa, pega uma faca e volta três horas depois, golpeando o ofensor, que estava sentado e desarmado. Sobre a legítima defesa, é correto afirmar que", "opcoes": ["não existe, apenas porque Davi usou arma branca.", "existe, mas Davi responde pelo excesso culposo.", "existe, pois houve injusta provocação da vítima.", "existe na forma putativa, por ter havido ofensa anterior.", "não existe, pois não havia agressão atual ou iminente."], "gabarito": 4, "explicacao": "A legítima defesa exige reação moderada a agressão injusta, atual ou iminente (art. 25 do CP). Revidar horas depois, com a ofensa já encerrada, é vingança."}, {"materia": "pen", "texto_base": "", "enunciado": "Ao sair de um restaurante, Caio leva um guarda-chuva idêntico ao seu, supondo sinceramente que fosse dele. Na verdade, pertencia a outro cliente. A conduta de Caio é", "opcoes": ["furto simples, pois houve subtração de coisa alheia móvel, ainda que por engano.", "furto culposo, por falta do devido cuidado.", "apropriação de coisa achada.", "furto privilegiado, pelo pequeno valor da coisa.", "atípica, pois o erro de tipo exclui o dolo e não há furto culposo."], "gabarito": 4, "explicacao": "Caio errou sobre um elemento do tipo (“coisa alheia”). O erro de tipo exclui o dolo (art. 20 do CP), e, como o furto não admite a forma culposa, o fato é atípico."}, {"materia": "ppen", "texto_base": "", "enunciado": "Pelo Código de Processo Penal, o inquérito policial deve ser concluído, como regra, no prazo de", "opcoes": ["10 dias, se o indiciado estiver solto, e 30 dias, se estiver preso.", "15 dias, se o indiciado estiver preso, e 60 dias, se estiver solto.", "10 dias, se o indiciado estiver preso, e 30 dias, se estiver solto.", "5 dias, se o indiciado estiver preso, e 15 dias, se estiver solto.", "30 dias, em qualquer hipótese."], "gabarito": 2, "explicacao": "O art. 10 do CPP fixa 10 dias para indiciado preso, contados da prisão, e 30 dias para indiciado solto. Leis especiais trazem prazos próprios, como a Lei de Drogas."}, {"materia": "ppen", "texto_base": "", "enunciado": "Logo após furtar uma bolsa, um homem é perseguido pela vítima e por populares, que não o perdem de vista, e acaba preso 40 minutos depois. Essa prisão em flagrante classifica-se como flagrante", "opcoes": ["preparado (ou provocado).", "presumido (ou ficto).", "diferido (ou retardado).", "próprio (ou real).", "impróprio (ou quase flagrante)."], "gabarito": 4, "explicacao": "Quando o agente é perseguido logo após o crime, em situação que faça presumir ser ele o autor, há flagrante impróprio (art. 302, III, do CPP). Não há limite fixo de tempo, desde que a perseguição seja contínua."}, {"materia": "ppen", "texto_base": "", "enunciado": "Lavrado o auto de prisão em flagrante, a nota de culpa deve ser entregue ao preso no prazo de", "opcoes": ["24 horas, mas apenas se o preso não tiver advogado constituído.", "5 dias, contados da comunicação da prisão ao Ministério Público.", "48 horas, assinada pelo juiz responsável pela audiência de custódia.", "72 horas, junto com a cópia integral do inquérito.", "24 horas, assinada pela autoridade, com o motivo da prisão."], "gabarito": 4, "explicacao": "O art. 306, § 2º, do CPP manda entregar ao preso, em até 24 horas da prisão, a nota de culpa assinada pela autoridade, com o motivo da prisão e os nomes do condutor e das testemunhas."}, {"materia": "ppen", "texto_base": "", "enunciado": "Após a prisão em flagrante, o preso deve ser apresentado ao juiz em audiência de custódia no prazo de até", "opcoes": ["24 horas.", "72 horas.", "10 dias.", "48 horas.", "5 dias."], "gabarito": 0, "explicacao": "O art. 310 do CPP, com redação do Pacote Anticrime, prevê a audiência de custódia em até 24 horas após a prisão, com a presença do acusado, de seu advogado ou defensor público e do Ministério Público."}, {"materia": "ppen", "texto_base": "", "enunciado": "Concluídas as investigações, o delegado entende que não houve crime. Nesse caso, ele", "opcoes": ["deve submeter o arquivamento ao chefe de polícia.", "deve arquivar o inquérito e comunicar o Ministério Público em 48 horas.", "pode arquivar o inquérito, comunicando a vítima.", "pode arquivar o inquérito, desde que o indiciado concorde.", "não pode arquivar o inquérito e deve relatá-lo e remetê-lo à Justiça."], "gabarito": 4, "explicacao": "A autoridade policial não pode mandar arquivar autos de inquérito (art. 17 do CPP). Ela relata e remete os autos, e quem promove o arquivamento é o Ministério Público."}, {"materia": "ppen", "texto_base": "", "enunciado": "A vítima requer a instauração de inquérito policial, mas o delegado indefere o pedido. Pelo Código de Processo Penal, contra esse despacho cabe", "opcoes": ["recurso para o chefe de Polícia.", "apelação ao Tribunal de Justiça.", "recurso em sentido estrito ao juiz.", "nenhum recurso, pois a decisão é irrecorrível.", "reclamação ao Ministério Público, com efeito suspensivo."], "gabarito": 0, "explicacao": "O art. 5º, § 2º, do CPP prevê que, do despacho que indeferir o requerimento de abertura de inquérito, caberá recurso para o chefe de Polícia."}, {"materia": "ppen", "texto_base": "", "enunciado": "Em investigação de crime hediondo, a prisão temporária pode ser decretada pelo prazo de", "opcoes": ["5 dias, prorrogável por mais 5.", "60 dias, prorrogável uma única vez por decisão fundamentada do juiz.", "30 dias, prorrogável por mais 30 em caso de extrema necessidade.", "15 dias, prorrogável por mais 15.", "10 dias, improrrogável."], "gabarito": 2, "explicacao": "Nos crimes hediondos e equiparados, a temporária é de 30 dias, prorrogáveis por mais 30 em caso de extrema e comprovada necessidade (Lei 8.072/1990, art. 2º, § 4º). Nos demais crimes, o prazo é de 5 + 5 dias."}, {"materia": "ppen", "texto_base": "", "enunciado": "Em crime de ação penal privada, como a calúnia, o inquérito policial", "opcoes": ["depende de autorização judicial prévia.", "não pode ser instaurado em nenhuma hipótese.", "só pode ser instaurado por requisição do Ministério Público.", "só pode ser instaurado a requerimento de quem tenha qualidade para ajuizar a ação.", "deve ser instaurado de ofício pelo delegado assim que tomar conhecimento do fato criminoso."], "gabarito": 3, "explicacao": "Nos crimes de ação privada, a autoridade policial só pode instaurar inquérito a requerimento de quem tenha qualidade para intentá-la (art. 5º, § 5º, do CPP)."}, {"materia": "ppen", "texto_base": "", "enunciado": "Preso em flagrante, um homem apresenta carteira de identidade com rasura que impede verificar se o documento é autêntico. Sobre a identificação criminal, é correto afirmar que", "opcoes": ["ela é obrigatória para todo preso em flagrante.", "ela depende do consentimento expresso do preso.", "ela só pode ser feita com autorização prévia e expressa do Ministério Público.", "ela pode ser feita, embora o preso tenha apresentado documento civil.", "ela é vedada, pois o preso apresentou identidade civil."], "gabarito": 3, "explicacao": "O civilmente identificado não será identificado criminalmente, salvo nas hipóteses legais (art. 5º, LVIII, da CF). A Lei 12.037/2009 (art. 3º, I) admite a identificação criminal quando o documento tiver rasura ou indício de falsificação."}, {"materia": "leg", "texto_base": "", "enunciado": "Dois homens se associam, de forma estável, para praticar tráfico de drogas, mas são presos antes de concluir a primeira venda. Pela Lei 11.343/2006, a associação para o tráfico (art. 35) exige", "opcoes": ["no mínimo três pessoas, com estabilidade, permanência e divisão de tarefas.", "a efetiva consumação de ao menos um crime de tráfico.", "quatro ou mais pessoas, estruturalmente ordenadas.", "a apreensão de droga em poder de todos os associados.", "duas ou mais pessoas, para praticar os crimes reiteradamente ou não."], "gabarito": 4, "explicacao": "O art. 35 da Lei 11.343/2006 pune a associação de duas ou mais pessoas para praticar, reiteradamente ou não, os crimes de tráfico. Organização criminosa (Lei 12.850/2013) exige quatro ou mais pessoas."}, {"materia": "leg", "texto_base": "", "enunciado": "O chefe de plantão vê agentes submetendo um preso a intenso sofrimento físico como castigo e nada faz, embora tivesse o dever de impedir. Pela Lei 9.455/1997, o chefe", "opcoes": ["responde por tortura com a mesma pena dos agentes, de 2 a 8 anos de reclusão.", "não comete crime, pois não praticou nenhum ato de violência.", "comete só infração disciplinar.", "responde por tortura na forma omissiva, com pena de detenção de 1 a 4 anos.", "responde apenas por prevaricação."], "gabarito": 3, "explicacao": "O art. 1º, § 2º, da Lei de Tortura pune quem se omite diante dessas condutas, quando tinha o dever de evitá-las ou apurá-las, com detenção de 1 a 4 anos."}, {"materia": "leg", "texto_base": "", "enunciado": "Em uma abordagem, um homem é flagrado portando pistola de calibre de uso permitido, com o número de série raspado. Pelo Estatuto do Desarmamento, ele responde", "opcoes": ["por posse irregular de arma de uso permitido (art. 12).", "por contravenção penal de porte de arma.", "pelo crime do art. 16, § 1º, IV, mesmo sendo a arma de uso permitido.", "pelo art. 14, com causa de aumento de metade da pena.", "por porte ilegal de arma de fogo de uso permitido (art. 14 do Estatuto), apenas."], "gabarito": 2, "explicacao": "Portar arma com numeração raspada, suprimida ou adulterada é equiparado ao porte de arma de uso restrito (art. 16, § 1º, IV), qualquer que seja o calibre, conforme entende o STJ."}, {"materia": "leg", "texto_base": "", "enunciado": "Pela Lei 13.869/2019, as condutas nela descritas só constituem crime de abuso de autoridade quando praticadas", "opcoes": ["por qualquer agente público, com dolo ou culpa.", "com finalidade de prejudicar outrem, beneficiar a si ou a terceiro, ou por capricho.", "com violência ou grave ameaça contra a pessoa.", "por autoridade policial no exercício de função de polícia judiciária, em qualquer hipótese.", "mediante resultado lesivo comprovado por laudo pericial."], "gabarito": 1, "explicacao": "O art. 1º, § 1º, exige dolo específico: finalidade de prejudicar outrem, beneficiar a si mesmo ou a terceiro, ou mero capricho ou satisfação pessoal. Não há modalidade culposa."}, {"materia": "leg", "texto_base": "", "enunciado": "Pela Lei 12.850/2013, a infiltração de agentes de polícia em organização criminosa", "opcoes": ["pode ser decidida pelo próprio delegado, que comunica o juiz em até 24 horas.", "exige autorização do Secretário de Segurança Pública.", "depende só de requisição do Ministério Público, por até 1 ano.", "é permitida por até 30 dias, improrrogáveis.", "depende de autorização judicial e dura até 6 meses, admitidas renovações."], "gabarito": 4, "explicacao": "A infiltração precisa de autorização judicial circunstanciada, motivada e sigilosa (art. 10) e vale por até 6 meses, sem prejuízo de renovações, desde que comprovada a necessidade (art. 10, § 3º)."}, {"materia": "leg", "texto_base": "", "enunciado": "Uma criança de 11 anos subtrai um aparelho celular de um colega. Pelo Estatuto da Criança e do Adolescente, ela", "opcoes": ["deve cumprir medida de semiliberdade.", "pode receber advertência e liberdade assistida.", "fica sujeita a internação provisória por até 45 dias.", "fica sujeita a medidas de proteção, e não a medidas socioeducativas.", "responde por furto, com pena reduzida pela metade em razão da menoridade."], "gabarito": 3, "explicacao": "Criança é quem tem até 12 anos incompletos. Ao ato infracional praticado por criança correspondem as medidas de proteção do art. 101 (art. 105 do ECA). Medidas socioeducativas são para adolescentes."}, {"materia": "leg", "texto_base": "", "enunciado": "Pela Lei 9.099/1995, consideram-se infrações de menor potencial ofensivo", "opcoes": ["os crimes culposos, qualquer que seja a pena.", "as contravenções penais e os crimes com pena máxima não superior a 2 anos.", "apenas as contravenções penais.", "os crimes com pena máxima não superior a 4 anos, inclusive os de violência doméstica.", "os crimes com pena mínima não superior a 1 ano."], "gabarito": 1, "explicacao": "O art. 61 da Lei 9.099/1995 define as infrações de menor potencial ofensivo: contravenções penais e crimes com pena máxima não superior a 2 anos, cumulada ou não com multa. Pena mínima de até 1 ano é critério da suspensão condicional do processo."}, {"materia": "leg", "texto_base": "", "enunciado": "Pelo Código de Trânsito Brasileiro, configura o crime de embriaguez ao volante (art. 306) conduzir veículo com concentração de álcool", "opcoes": ["superior a 0,05 mg por litro de ar alveolar, qualquer que seja o resultado.", "igual ou superior a 2 dg por litro de sangue ou a 0,1 mg por litro de ar alveolar.", "igual ou superior a 6 dg por litro de sangue ou a 0,3 mg por litro de ar alveolar.", "igual ou superior a 10 dg por litro de sangue.", "qualquer, desde que o condutor cause acidente."], "gabarito": 2, "explicacao": "O art. 306, § 1º, I, do CTB fixa os limites do crime: 6 decigramas por litro de sangue ou 0,3 miligrama por litro de ar alveolar. Abaixo disso, há infração administrativa."}, {"materia": "leg", "texto_base": "", "enunciado": "Condenado primário por crime hediondo sem resultado morte, um réu pede a progressão de regime. Pela Lei de Execução Penal, após o Pacote Anticrime, ele deve cumprir ao menos", "opcoes": ["2/5 da pena, se tiver bom comportamento, e 3/5 sem ele.", "50% da pena.", "60% da pena.", "40% da pena.", "1/6 da pena."], "gabarito": 3, "explicacao": "O art. 112, V, da LEP exige 40% da pena para o primário condenado por crime hediondo ou equiparado. São 50% se houver resultado morte e 60% para o reincidente em hediondo."}, {"materia": "cont", "texto_base": "", "enunciado": "Uma empresa tem ativo total de R$ 500.000,00 e obrigações com terceiros de R$ 320.000,00. Seu patrimônio líquido é de", "opcoes": ["R$ 160.000,00.", "R$ 320.000,00.", "R$ 180.000,00.", "R$ 820.000,00.", "R$ 500.000,00."], "gabarito": 2, "explicacao": "Pela equação patrimonial, Ativo = Passivo + PL. Então PL = 500.000 − 320.000 = 180.000."}, {"materia": "cont", "texto_base": "", "enunciado": "Pelo método das partidas dobradas, aumentam por lançamentos a crédito as contas de", "opcoes": ["receita, despesa e ativo.", "ativo, despesa e custo.", "passivo, patrimônio líquido e receita.", "ativo, passivo e receita.", "despesa, patrimônio líquido, ativo e custo."], "gabarito": 2, "explicacao": "Contas de natureza credora (passivo, PL e receitas) aumentam a crédito. Contas de natureza devedora (ativo, despesas e custos) aumentam a débito."}, {"materia": "cont", "texto_base": "", "enunciado": "Uma empresa vende mercadorias a prazo. No registro da receita dessa venda, o lançamento contábil é", "opcoes": ["D – Clientes (Duplicatas a Receber); C – Receita de Vendas.", "D – Fornecedores; C – Receita de Vendas.", "D – Receita de Vendas; C – Clientes (Duplicatas a Receber).", "D – Caixa; C – Receita de Vendas.", "D – Clientes (Duplicatas a Receber); C – Mercadorias."], "gabarito": 0, "explicacao": "Na venda a prazo surge um direito a receber (ativo, debitado) e uma receita (creditada). Caixa só seria debitado na venda à vista."}, {"materia": "cont", "texto_base": "", "enunciado": "Integra o passivo circulante de uma empresa a conta", "opcoes": ["Estoques de Mercadorias.", "Clientes (Duplicatas a Receber).", "Veículos.", "Capital Social.", "Fornecedores."], "gabarito": 4, "explicacao": "Fornecedores são obrigações de curto prazo: passivo circulante. Clientes e Estoques são ativo circulante, Veículos é ativo imobilizado e Capital Social é patrimônio líquido."}, {"materia": "cont", "texto_base": "", "enunciado": "O pagamento de uma duplicata a um fornecedor, sem juros nem desconto, é um fato contábil", "opcoes": ["permutativo, pois não altera o patrimônio líquido.", "modificativo aumentativo, pois reduz o passivo.", "modificativo diminutivo, pois reduz o ativo.", "modificativo, pois altera o total do ativo.", "misto, pois altera ativo e passivo ao mesmo tempo."], "gabarito": 0, "explicacao": "Sai dinheiro do ativo e sai a dívida do passivo no mesmo valor, sem mexer no patrimônio líquido: é fato permutativo. Com juros, seria misto diminutivo."}, {"materia": "cont", "texto_base": "", "enunciado": "Uma empresa tem ativo circulante de R$ 150.000,00 e passivo circulante de R$ 100.000,00. Seu índice de liquidez corrente é", "opcoes": ["50.000.", "1,0.", "1,5.", "0,67.", "2,5."], "gabarito": 2, "explicacao": "Liquidez corrente = Ativo Circulante / Passivo Circulante = 150.000 / 100.000 = 1,5. Para cada real de dívida de curto prazo, a empresa tem R$ 1,50 de bens e direitos de curto prazo."}, {"materia": "cont", "texto_base": "", "enunciado": "Em 1º de julho, uma empresa paga R$ 12.000,00 por um seguro com vigência de 12 meses. Em 31 de dezembro do mesmo ano, o valor que ainda permanece no ativo como despesa antecipada é de", "opcoes": ["R$ 6.000,00.", "zero.", "R$ 12.000,00.", "R$ 1.000,00.", "R$ 3.000,00."], "gabarito": 0, "explicacao": "Pelo regime de competência, a despesa é apropriada mês a mês: R$ 1.000,00 por mês. De julho a dezembro passam 6 meses, ou R$ 6.000,00 de despesa, e os outros R$ 6.000,00 continuam no ativo."}, {"materia": "cont", "texto_base": "", "enunciado": "Uma empresa presta um serviço em dezembro e recebe o pagamento só em janeiro do ano seguinte. Pelo regime de competência, a receita deve ser reconhecida", "opcoes": ["em dezembro, quando o serviço foi prestado.", "na data de emissão da nota fiscal do ano seguinte.", "em janeiro, quando o dinheiro entrou no caixa.", "só no balanço anual do ano seguinte.", "metade em dezembro e metade em janeiro."], "gabarito": 0, "explicacao": "No regime de competência, receitas e despesas são reconhecidas no período em que ocorrem, independentemente de recebimento ou pagamento. Receber em janeiro seria o critério do regime de caixa."}, {"materia": "const", "texto_base": "", "enunciado": "Às 2h da madrugada, policiais ouvem gritos de socorro vindos de uma casa e percebem que uma mulher está sendo agredida. Pela Constituição Federal, eles", "opcoes": ["podem entrar só se acompanhados de um oficial de justiça.", "só podem entrar com consentimento do morador.", "podem entrar sem mandado, pois há flagrante delito.", "só podem entrar com mandado judicial, por ser noite.", "devem aguardar o amanhecer para entrar."], "gabarito": 2, "explicacao": "A casa é asilo inviolável, mas se pode entrar sem consentimento em caso de flagrante delito, desastre ou para prestar socorro, a qualquer hora. Por determinação judicial, só durante o dia (art. 5º, XI)."}, {"materia": "const", "texto_base": "", "enunciado": "Um cidadão quer conhecer e retificar informações a seu respeito constantes de banco de dados de um órgão público, que se recusa a fornecê-las. O remédio constitucional adequado é o", "opcoes": ["ação popular.", "habeas corpus.", "habeas data.", "mandado de injunção.", "mandado de segurança."], "gabarito": 2, "explicacao": "O habeas data serve para conhecer e retificar informações sobre a pessoa do impetrante em registros de entidades governamentais ou de caráter público (art. 5º, LXXII)."}, {"materia": "const", "texto_base": "", "enunciado": "Pela Constituição Federal, a prisão de qualquer pessoa e o local onde se encontre devem ser comunicados", "opcoes": ["imediatamente ao delegado-geral e ao juiz.", "em até 72 horas ao juiz competente.", "em até 24 horas apenas à família do preso.", "imediatamente ao juiz competente e à família do preso ou a pessoa por ele indicada.", "em até 48 horas ao Ministério Público e à Defensoria Pública, se o preso não tiver advogado."], "gabarito": 3, "explicacao": "O art. 5º, LXII, manda comunicar a prisão e o local onde a pessoa se encontra imediatamente ao juiz competente e à família do preso ou à pessoa por ele indicada."}, {"materia": "const", "texto_base": "", "enunciado": "Ao lavrar o auto de prisão em flagrante, o delegado deve informar ao preso, entre outros direitos assegurados pela Constituição Federal,", "opcoes": ["o direito de ser ouvido só depois da audiência de custódia.", "o direito de ser solto mediante fiança, em qualquer caso.", "o dever de responder a todas as perguntas da autoridade, sob pena de confissão ficta.", "o direito de permanecer calado, assegurada a assistência da família e de advogado.", "o dever de indicar testemunhas a seu favor no prazo de 24 horas."], "gabarito": 3, "explicacao": "O art. 5º, LXIII, da CF assegura que o preso será informado de seus direitos, entre os quais o de permanecer calado, com a assistência da família e de advogado. O silêncio não importa confissão."}, {"materia": "const", "texto_base": "", "enunciado": "Pela Constituição Federal, NÃO é cargo privativo de brasileiro nato o de", "opcoes": ["oficial das Forças Armadas (Exército, Marinha e Aeronáutica).", "Ministro do Superior Tribunal de Justiça.", "Ministro de Estado da Defesa.", "Ministro do Supremo Tribunal Federal.", "Presidente do Senado Federal."], "gabarito": 1, "explicacao": "O art. 12, § 3º, lista os cargos privativos de nato: Presidente e Vice, presidentes da Câmara e do Senado, Ministro do STF, carreira diplomática, oficial das Forças Armadas e Ministro da Defesa. Ministro do STJ não está na lista."}, {"materia": "const", "texto_base": "", "enunciado": "Pela Constituição Federal, a idade mínima para concorrer ao cargo de governador de Estado é de", "opcoes": ["21 anos.", "18 anos.", "25 anos.", "30 anos.", "35 anos."], "gabarito": 3, "explicacao": "Pelo art. 14, § 3º, VI, as idades mínimas são: 35 anos para Presidente, Vice e Senador; 30 para Governador e Vice; 21 para Deputado e Prefeito; e 18 para Vereador."}, {"materia": "const", "texto_base": "", "enunciado": "Um direito previsto na Constituição não pode ser exercido porque falta a lei que o regulamente. O remédio constitucional cabível é o", "opcoes": ["habeas data.", "mandado de injunção.", "ação civil pública.", "mandado de segurança.", "habeas corpus."], "gabarito": 1, "explicacao": "Cabe mandado de injunção sempre que a falta de norma regulamentadora tornar inviável o exercício de direitos e liberdades constitucionais (art. 5º, LXXI)."}, {"materia": "const", "texto_base": "", "enunciado": "Pela Constituição Federal, é competência do Tribunal do Júri julgar", "opcoes": ["os crimes cometidos por autoridades.", "os crimes contra a vida, dolosos ou culposos.", "o latrocínio e o homicídio.", "os crimes dolosos contra a vida.", "todos os crimes hediondos."], "gabarito": 3, "explicacao": "O art. 5º, XXXVIII, “d”, assegura ao júri o julgamento dos crimes dolosos contra a vida. O latrocínio é crime contra o patrimônio e vai ao juiz singular (Súmula 603 do STF)."}, {"materia": "adm", "texto_base": "", "enunciado": "A vigilância sanitária interdita, no mesmo dia, um restaurante com alimentos estragados, sem precisar de ordem judicial. Esse ato demonstra o atributo da", "opcoes": ["tipicidade.", "imperatividade, apenas no aspecto formal.", "presunção de legitimidade.", "autoexecutoriedade.", "motivação dispensável."], "gabarito": 3, "explicacao": "Autoexecutoriedade é a possibilidade de a Administração executar seus atos diretamente, sem ordem judicial, em especial em situações urgentes ou quando a lei autoriza."}, {"materia": "adm", "texto_base": "", "enunciado": "A prefeitura aplica multa a um estabelecimento comercial que funcionava sem alvará. A Administração exerceu o poder", "opcoes": ["vinculado de tutela.", "disciplinar.", "de polícia.", "hierárquico.", "regulamentar."], "gabarito": 2, "explicacao": "Poder de polícia é a atividade que limita e condiciona o uso de bens, o exercício de atividades e direitos individuais em favor do interesse público, inclusive com multas a particulares. O poder disciplinar alcança servidores e quem tem vínculo especial com a Administração."}, {"materia": "adm", "texto_base": "", "enunciado": "A Administração decide retirar um ato administrativo válido que deixou de ser conveniente e oportuno. Trata-se de", "opcoes": ["cassação, por descumprimento de condições.", "anulação, com efeitos retroativos (ex tunc).", "revogação, com efeitos a partir de então (ex nunc).", "anulação, com efeitos apenas a partir da decisão (ex nunc).", "convalidação, para corrigir o vício."], "gabarito": 2, "explicacao": "A revogação retira ato válido por conveniência e oportunidade, com efeitos ex nunc, e só a própria Administração pode revogar. A anulação retira ato ilegal, em regra com efeitos ex tunc (Súmula 473 do STF)."}, {"materia": "adm", "texto_base": "", "enunciado": "Uma viatura da polícia, em perseguição, colide com o carro de um particular, que sofre prejuízo. Pela Constituição Federal, a responsabilidade do Estado é", "opcoes": ["objetiva, com direito de regresso contra o agente em caso de dolo ou culpa.", "subjetiva, dependendo de prova de culpa do motorista da viatura.", "inexistente, pois o policial agia no estrito cumprimento do dever legal de perseguir.", "solidária entre o Estado e o policial, sem regresso.", "objetiva, sem direito de regresso contra o agente."], "gabarito": 0, "explicacao": "O art. 37, § 6º, adota a responsabilidade objetiva (teoria do risco administrativo): o particular não precisa provar culpa, e o Estado pode cobrar do agente se este agiu com dolo ou culpa."}, {"materia": "adm", "texto_base": "", "enunciado": "Um secretário estadual manda publicar propaganda de uma obra com sua foto e o slogan “obra do secretário”. Essa publicidade viola diretamente o princípio da", "opcoes": ["publicidade.", "eficiência.", "continuidade do serviço público.", "impessoalidade.", "legalidade estrita, apenas."], "gabarito": 3, "explicacao": "A publicidade oficial deve ter caráter educativo, informativo ou de orientação social, sem nomes, símbolos ou imagens que caracterizem promoção pessoal (art. 37, § 1º), o que concretiza a impessoalidade."}, {"materia": "adm", "texto_base": "", "enunciado": "Pela Constituição Federal, o servidor nomeado para cargo de provimento efetivo, em virtude de concurso público, adquire estabilidade após", "opcoes": ["1 ano de estágio probatório e aprovação em prova interna.", "3 anos da data da posse, independentemente de avaliação.", "2 anos de efetivo exercício, automaticamente.", "3 anos de efetivo exercício e aprovação em avaliação especial de desempenho.", "5 anos de efetivo exercício e aprovação em curso de formação profissional específico."], "gabarito": 3, "explicacao": "O art. 41 exige 3 anos de efetivo exercício e, como condição para a estabilidade, avaliação especial de desempenho por comissão instituída para esse fim (§ 4º)."}, {"materia": "adm", "texto_base": "", "enunciado": "O delegado titular distribui as tarefas entre os investigadores da delegacia, dá ordens e fiscaliza o seu cumprimento. Ele exerce o poder", "opcoes": ["de polícia.", "hierárquico.", "normativo.", "disciplinar.", "regulamentar."], "gabarito": 1, "explicacao": "Distribuir e escalonar funções, dar ordens e fiscalizar subordinados é expressão do poder hierárquico. O disciplinar seria usado para punir infrações funcionais."}, {"materia": "adm", "texto_base": "", "enunciado": "Sobre as autarquias, é correto afirmar que", "opcoes": ["podem ser criadas por decreto do chefe do Executivo.", "são órgãos da administração direta, sem personalidade própria.", "não se sujeitam ao controle do ente que as criou.", "são criadas por lei específica e têm personalidade jurídica de direito público.", "têm a criação apenas autorizada por lei e personalidade jurídica de direito privado."], "gabarito": 3, "explicacao": "Pelo art. 37, XIX, da CF, a autarquia é criada por lei específica. É pessoa jurídica de direito público da administração indireta, sujeita ao controle (tutela) do ente criador. Empresas públicas e sociedades de economia mista têm a criação autorizada por lei."}, {"materia": "est", "texto_base": "", "enunciado": "Em cinco dias, uma delegacia registrou 4, 8, 6, 10 e 7 ocorrências. A média diária de ocorrências foi de", "opcoes": ["35.", "6,5.", "8.", "6.", "7."], "gabarito": 4, "explicacao": "Média = (4 + 8 + 6 + 10 + 7) / 5 = 35 / 5 = 7."}, {"materia": "est", "texto_base": "", "enunciado": "Os tempos de chegada de uma viatura a cinco ocorrências foram 8, 15, 10, 22 e 12 minutos. A mediana desses tempos é", "opcoes": ["22 minutos.", "13,4 minutos.", "10 minutos.", "15 minutos.", "12 minutos."], "gabarito": 4, "explicacao": "Em ordem: 8, 10, 12, 15, 22. Com cinco valores, a mediana é o do meio, o 3º: 12. A média seria 67/5 = 13,4."}, {"materia": "est", "texto_base": "", "enunciado": "Em um curso de formação, a prova teórica tem peso 2 e a prova prática tem peso 3. Um aluno tirou 6 na teórica e 9 na prática. Sua média ponderada é", "opcoes": ["8,0.", "7,8.", "7,5.", "7,2.", "8,4."], "gabarito": 1, "explicacao": "Média ponderada = (6·2 + 9·3) / (2 + 3) = (12 + 27) / 5 = 39/5 = 7,8. A média simples seria 7,5."}, {"materia": "est", "texto_base": "", "enunciado": "Cinco investigadores têm 12, 4, 19, 7 e 15 anos de carreira. A amplitude desse conjunto é", "opcoes": ["15.", "12.", "11.", "7.", "19."], "gabarito": 0, "explicacao": "Amplitude total = maior valor − menor valor = 19 − 4 = 15."}, {"materia": "est", "texto_base": "", "enunciado": "Um conjunto de dados tem média 50 e desvio padrão 10. O seu coeficiente de variação é", "opcoes": ["5%.", "20%.", "10%.", "40%.", "50%."], "gabarito": 1, "explicacao": "Coeficiente de variação = desvio padrão / média = 10 / 50 = 0,2 = 20%."}, {"materia": "est", "texto_base": "", "enunciado": "Se a variância de um conjunto de dados é 25, o desvio padrão é", "opcoes": ["25.", "625.", "12,5.", "2,5.", "5."], "gabarito": 4, "explicacao": "O desvio padrão é a raiz quadrada da variância: √25 = 5."}, {"materia": "est", "texto_base": "", "enunciado": "Lançando-se um dado comum, não viciado, a probabilidade de sair um número maior que 4 é", "opcoes": ["1/3.", "1/2.", "1/6.", "5/6.", "2/3."], "gabarito": 0, "explicacao": "Números maiores que 4 são o 5 e o 6, dois casos favoráveis em seis possíveis: 2/6 = 1/3."}, {"materia": "est", "texto_base": "", "enunciado": "Em uma pesquisa sobre segurança pública, a variável “número de ocorrências registradas por dia” é classificada como", "opcoes": ["quantitativa discreta.", "qualitativa discreta.", "quantitativa contínua.", "qualitativa nominal.", "qualitativa ordinal."], "gabarito": 0, "explicacao": "É uma contagem, com valores inteiros (0, 1, 2...), então é quantitativa discreta. Variáveis medidas, como peso e tempo, são contínuas."}]$q$::jsonb;
begin
  insert into public.simulados (trilha, data, titulo, estilo, duracao_min, publicado)
  values ('policial', date '2026-11-15', 'Simulado 4 · Policial', 'AOCP', 240, true)
  on conflict (trilha, data) do update set titulo = excluded.titulo, estilo = excluded.estilo, duracao_min = excluded.duracao_min
  returning id into sid;
  if exists (select 1 from public.simulado_respostas r where r.simulado_id = sid) then
    raise notice 'Simulado já iniciado por alguém: questões mantidas.';
  else
    delete from public.simulado_questoes where simulado_id = sid;
    insert into public.simulado_questoes (simulado_id, ordem, materia, texto_base, enunciado, opcoes, gabarito, explicacao)
    select sid, e.n, e.v ->> 'materia', nullif(e.v ->> 'texto_base', ''), e.v ->> 'enunciado', e.v -> 'opcoes', (e.v ->> 'gabarito')::smallint, e.v ->> 'explicacao'
      from jsonb_array_elements(lista) with ordinality e(v, n);
    update public.simulados set publicado = true where id = sid;
  end if;
end $$;

select s.id, s.trilha, s.data - 1 as abre_sabado, s.data as fecha_domingo, s.titulo, s.estilo, s.duracao_min, s.publicado, count(q.ordem) as questoes
  from public.simulados s left join public.simulado_questoes q on q.simulado_id = s.id
 where s.trilha = 'policial' and s.data = date '2026-11-15' group by s.id;
